import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import "./App.scss";
import LoginRegisterForm from "./components/LoginRegisterContainer/LoginRegisterContainer";
import AdminCustomerContainer from "./components/AdminCustomerContainer/AdminCustomerContainer";
import SellerContainer from "./components/SellerContainer/SellerContainer";
import ProfileUpdate from "./components/ProfileUpdate/ProfileUpdate";

function App() {
  let [isUserAuthenticated, setUserAuthorization] = useState(
    sessionStorage.getItem("isUserAuthenticated") === "true" || false
  );
  let [isAdmin, setAdmin] = useState(
    parseInt(sessionStorage.getItem("isAdmin"), 10) || 0 // Convert to number for strict comparisons
  );
  let [customerId, setCustomerId] = useState(
    sessionStorage.getItem("customerId") || undefined
  );

  const setUserAuthenticatedStatus = (isAdmin, customerId) => {
    setUserAuthorization(true);
    setAdmin(isAdmin);
    setCustomerId(customerId);
  };

  const handleLogout = () => {
    sessionStorage.removeItem("isUserAuthenticated");
    sessionStorage.removeItem("isAdmin");
    sessionStorage.removeItem("customerId");

    setUserAuthorization(false);
    setAdmin(0); // Reset to default role (user)
    setCustomerId(undefined);
  };

  const cancelOrder = (orderId) => {
    console.log("Cancel Order:", orderId);
    // API call to cancel the order
  };

  const validateOrder = (orderId) => {
    console.log("Validate Order:", orderId);
    // API call to validate the order
  };

  const modifyStock = (productId, newStock) => {
    console.log("Modify Stock:", productId, newStock);
    // API call to modify the stock
  };

  return (
    <Router>
      <Routes>
        {/* Route pour le formulaire de connexion/inscription */}
        <Route
          path="/"
          element={
            !isUserAuthenticated ? (
              <LoginRegisterForm setUserAuthenticatedStatus={setUserAuthenticatedStatus} />
            ) : (
              <>
                <div className="login-button-container">
                  <button
                    onClick={() => {
                      const userId = sessionStorage.getItem("customerId");
                      window.location.href = `/update-profile?userId=${userId}`;
                    }}
                    className="login-button"
                  >
                    Update Profile
                  </button>
                </div>
                <div className="login-button-container">
                  <button onClick={handleLogout} className="login-button">
                    Logout
                  </button>
                </div>
                {/* Affichage conditionnel basé sur le rôle */}
                <div className="action-buttons">
                  {isAdmin === 0 && (
                    <button onClick={() => cancelOrder("order123")}>
                      Cancel Order
                    </button>
                  )}
                  {(isAdmin === 2 || isAdmin === 1) && (
                    <button onClick={() => validateOrder("order123")}>
                      Validate Order
                    </button>
                  )}
                  {isAdmin === 1 && (
                    <button onClick={() => modifyStock("product123", 50)}>
                      Modify Stock
                    </button>
                  )}
                </div>
                {isAdmin === 2 ? (
                  <SellerContainer />
                ) : (
                  <AdminCustomerContainer isAdmin={isAdmin} customerId={customerId} />
                )}
              </>
            )
          }
        />

        {/* Route pour la mise à jour du profil */}
        <Route path="/update-profile" element={<ProfileUpdate />} />
      </Routes>
    </Router>
  );
}

export default App;
